import React, { useState } from 'react';
import { trackEvent } from '../services/tracking';
import { CONFIG } from '../constants';

const LeadForm: React.FC = () => {
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setStatus('loading');

    const formData = new FormData(e.currentTarget);
    const data = Object.fromEntries(formData.entries());

    try {
      // Netlify Forms Submission
      await fetch("/", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams(formData as any).toString(),
      });

      trackEvent('lead_submitted', { specialty: data.especialidad });

      // Optional Webhook
      if (CONFIG.WEBHOOK_URL) {
        try {
          await fetch(CONFIG.WEBHOOK_URL, {
            method: 'POST',
            body: JSON.stringify(data),
          });
        } catch (e) { console.error("Webhook failed", e); }
      }

      setStatus('success');
    } catch (error) {
      console.error(error);
      setStatus('error');
    }
  };

  if (status === 'success') {
    return (
      <section id="inscripcion" className="py-20 bg-brand-primary text-white text-center">
        <div className="max-w-2xl mx-auto px-4">
          <div className="bg-white text-slate-900 p-8 rounded-2xl shadow-xl">
            <svg className="w-16 h-16 text-green-500 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
            <h3 className="text-2xl font-bold mb-2">Solicitud Enviada con Éxito</h3>
            <p className="text-slate-600 mb-6">Un asesor académico se pondrá en contacto con usted en las próximas 24 h laborables para formalizar su plaza.</p>
            <button 
              onClick={() => setStatus('idle')}
              className="text-brand-primary font-bold hover:underline"
            >
              Volver al formulario
            </button>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section id="inscripcion" className="py-20 bg-slate-900 text-white scroll-mt-header">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold mb-4">Solicite más información o formalice su pre-inscripción</h2>
          <p className="text-slate-400">Sin compromiso. Nos pondremos en contacto para resolver sus dudas técnicas.</p>
        </div>

        <form 
          name="lead" 
          method="POST" 
          data-netlify="true" 
          netlify-honeypot="bot-field"
          onSubmit={handleSubmit}
          className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-white p-8 rounded-2xl text-slate-900 shadow-2xl"
        >
          {/* Netlify Hidden Fields */}
          <input type="hidden" name="form-name" value="lead" />
          <p className="hidden"><label>Don't fill this out if you're human: <input name="bot-field" /></label></p>

          <div className="col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Nombre completo</label>
            <input 
              type="text" 
              name="nombre" 
              required 
              placeholder="Dr/Dra. [Nombre]"
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-brand-primary outline-none transition-all"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Email profesional</label>
            <input 
              type="email" 
              name="email" 
              required 
              placeholder="email@institucion.com"
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-brand-primary outline-none transition-all"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">País de ejercicio</label>
            <input 
              type="text" 
              name="pais" 
              required 
              placeholder="Ej. España, México..."
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-brand-primary outline-none transition-all"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Especialidad</label>
            <input 
              type="text" 
              name="especialidad" 
              required 
              placeholder="Ej. Dermatología, Cirugía..."
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-brand-primary outline-none transition-all"
            />
          </div>

          <div className="col-span-2">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Mensaje / Dudas técnicas (Opcional)</label>
            <textarea 
              name="mensaje" 
              rows={3}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-brand-primary outline-none transition-all resize-none"
