          </div>

          <div className="col-span-2 flex items-start gap-3">
            <input type="checkbox" name="novedades" id="novedades" className="mt-1 accent-brand-primary" />
            <label htmlFor="novedades" className="text-sm text-slate-500">
              Deseo recibir actualizaciones sobre nueva evidencia científica y futuras cohortes.
            </label>
          </div>

          <div className="col-span-2">
            <button 
              type="submit" 
              disabled={status === 'loading'}
              className="w-full py-4 bg-brand-primary text-white font-bold rounded-lg hover:bg-brand-accent shadow-lg transition-all disabled:opacity-50"
            >
              {status === 'loading' ? 'Enviando...' : 'Enviar Solicitud'}
            </button>
            {status === 'error' && <p className="mt-2 text-red-500 text-sm text-center">Hubo un error. Inténtelo de nuevo o contacte a {CONFIG.SUPPORT_EMAIL}</p>}
          </div>
        </form>
      </div>
    </section>
  );
};

